  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.grid-3 {
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
}

/* Responsive Design */
@media (max-width: 600px) {
  :root {
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;
    --spacing-xxl: 2.5rem;
  }

  .site-header .container {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--spacing-sm);
    padding: var(--spacing-sm);
  }

  .site-header nav {
    width: 100%;
    flex-direction: column;
    gap: var(--spacing-sm);
  }

  .site-header nav a {
    display: block;
    padding: var(--spacing-xs) 0;
  }

  .logo {
    font-size: 1.1rem;
    padding: var(--spacing-xs) var(--spacing-sm);
  }

  .footer-content {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .grid-2,
  .grid-3 {
    grid-template-columns: 1fr;
  }

  button,
  input[type="submit"],
  .btn {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .site-header .container {
    padding: var(--spacing-md) var(--spacing-lg);
  }

  .site-header nav {
    gap: var(--spacing-xl);
  }

  button,
  input[type="submit"],
  .btn {
    width: auto;
  }

  .grid {
    gap: var(--spacing-xl);
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

pages.css:
.hero {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  color: #ffffff;
  padding: var(--spacing-xxl) var(--spacing-md);
  text-align: center;
}

.hero h1 {
  color: #ffffff;
  margin-bottom: var(--spacing-md);
}

.hero-tagline {
  font-size: 1.3rem;
  font-weight: 500;
  margin-bottom: var(--spacing-sm);
  color: var(--color-accent-on-dark);
}

.hero-description {
  font-size: 1.05rem;
  max-width: 600px;
  margin: var(--spacing-md) auto var(--spacing-lg);
  color: rgba(255, 255, 255, 0.95);
}

.hero .btn {
  background-color: var(--color-accent);
  color: var(--color-primary-dark);
  font-weight: 700;
  font-size: 1.05rem;
  margin-top: var(--spacing-md);
}

.hero .btn:hover {
  background-color: #ffffff;
}

.services-section,
.team-section,
.appointment-section,
.contact-section {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.services-section {
  background-color: var(--color-neutral-light);
}

.team-section {
  background-color: #ffffff;
}

.appointment-section {
  background-color: var(--color-neutral-light);
}

.contact-section {
  background-color: #ffffff;
}

.section-intro {
  font-size: 1.05rem;
  color: #666;
  max-width: 700px;
  margin-bottom: var(--spacing-lg);
}

.service-card {
  display: flex;
  flex-direction: column;
}

.service-card h3 {
  color: var(--color-primary);
}

.service-list {
  list-style: none;
  margin: var(--spacing-md) 0 0;
  padding: 0;
  flex-grow: 1;
}

.service-list li {
  padding-left: 1.5rem;
  position: relative;
  margin-bottom: var(--spacing-sm);
  font-size: 0.95rem;
}

.service-list li::before {
  content: "✓";
  position: absolute;
  left: 0;
  color: var(--color-success);
  font-weight: bold;
  font-size: 1.1rem;
}

.team-card {
  display: flex;
  flex-direction: column;
  text-align: center;
}

.team-photo {
  width: 100%;
  height: 280px;
  object-fit: cover;
  border-radius: 8px 8px 0 0;
  margin: -var(--spacing-lg) -var(--spacing-lg) var(--spacing-md) -var(--spacing-lg);
}

.team-title {
  color: var(--color-accent);
  font-weight: 600;
  font-size: 0.95rem;
  margin-bottom: var(--spacing-sm);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.team-credentials {
  font-size: 0.85rem;
  color: #999;
  margin-top: var(--spacing-md);
  padding-top: var(--spacing-md);
  border-top: 1px solid var(--color-border);
}

.appointment-form {
  max-width: 600px;
  margin: var(--spacing-lg) auto 0;
  background-color: #ffffff;
  padding: var(--spacing-lg);
  border-radius: 8px;
  border: 1px solid var(--color-border);
}

.form-legend {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
  padding-bottom: var(--spacing-md);
  border-bottom: 2px solid var(--color-accent);
  width: 100%;
}

fieldset {
  margin-bottom: var(--spacing-lg);
}

fieldset:last-of-type {
  margin-bottom: var(--spacing-md);
}

.form-group {
  margin-bottom: var(--spacing-md);
}

.required {
  color: #d32f2f;
  font-weight: bold;
}

.checkbox-group {
  display: flex;
  align-items: center;
}

.checkbox-group label {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  margin-bottom: 0;
  font-weight: 500;
}

.checkbox-group input[type="checkbox"] {
  width: auto;
  min-width: 20px;
  min-height: 20px;
  cursor: pointer;
}

.btn-appointment {
  margin-top: var(--spacing-md);
}

.contact-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
}

.contact-card {
  background-color: var(--color-neutral-light);
  padding: var(--spacing-lg);
  border-radius: 8px;
  border-left: 4px solid var(--color-accent);
}

.contact-card h3 {
  margin-top: 0;
  color: var(--color-primary);
}

.contact-card p {
  margin-bottom: var(--spacing-sm);
  line-height: 1.8;
}

.contact-card a {
  color: var(--color-primary);
  font-weight: 600;
}

.contact-card a:hover {
  color: var(--color-primary-dark);
}

.small-text {
  font-size: 0.9rem;
  color: #666;
  margin-bottom: 0;
}

@media (max-width: 600px) {
  .hero {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .hero h1 {
    font-size: 1.8rem;
  }

  .hero-tagline {
    font-size: 1.1rem;
  }

  .hero-description {
    font-size: 1rem;
    margin: var(--spacing-md) 0 var(--spacing-lg);
  }

  .services-section,
  .team-section,
  .appointment-section,
  .contact-section {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .appointment-form {
    padding: var(--spacing-md);
  }

  .team-photo {
    height: 200px;
    margin: -var(--spacing-md) -var(--spacing-md) var(--spacing-md) -var(--spacing-md);
  }

  input[type="submit"],
  .btn-appointment {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .hero {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .services-section,
  .team-section,
  .appointment-section,
  .contact-section {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .appointment-form {
    margin: var(--spacing-xl) auto 0;
  }

  .team-card {
    max-width: 100%;
  }
}
